(()=>{
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=null,model=null,reportText='',view='discover',selectedStage=null;
const steps=['discover','investigate','teach','scope','report'];
const format=n=>n===null?'Unavailable':Number(n).toFixed(1);
const stageChecks={
 'Application review':['Recruiting lead','Check who owns the first review and when new applications are picked up.'],
 'Recruiter screen':['Recruiting lead','Check screening capacity and the handoff to the next interview.'],
 'Hiring manager interview':['Hiring manager','Check interview availability and who follows up on feedback.'],
 'Technical / functional interview':['Hiring manager','Check interviewer capacity, scheduling handoffs and feedback turnaround.'],
 'Offer':['Talent Acquisition lead','Check approval steps and whether offer decisions have a clear owner.']
};
function scope(){return {objective:$('case-objective').value.trim(),target:$('case-target').value.trim(),owner:$('case-owner').value,review:$('case-review').value};}
function show(next,focus=false){if(!steps.includes(next))return;view=next;document.querySelectorAll('[data-caseview]').forEach(b=>{const selected=b.dataset.caseview===next;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});steps.forEach(id=>$('case-'+id+'-panel').hidden=id!==next);if(next==='report')renderReport();if(focus)$('case-tab-'+next).focus();}
document.querySelectorAll('[data-caseview]').forEach(b=>{b.onclick=()=>show(b.dataset.caseview);b.onkeydown=e=>{let i=steps.indexOf(view),n;if(e.key==='ArrowRight')n=steps[(i+1)%steps.length];else if(e.key==='ArrowLeft')n=steps[(i+steps.length-1)%steps.length];else if(e.key==='Home')n=steps[0];else if(e.key==='End')n=steps.at(-1);if(n){e.preventDefault();show(n,true);}};});
document.querySelectorAll('[data-casego]').forEach(b=>b.onclick=()=>show(b.dataset.casego,true));
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function roles(){if(!data)return;const team=$('case-team').value,existing=$('case-role').value;const options=[...new Map(data.events.filter(e=>!team||e.team===team).map(e=>[e.roleId,e.role])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));$('case-role').innerHTML='<option value="">All roles in team</option>'+options.map(([id,label])=>'<option value="'+esc(id)+'">'+esc(label)+'</option>').join('');$('case-role').value=options.some(([id])=>id===existing)?existing:'';}
function filters(){return {team:$('case-team').value,role:$('case-role').value,cohort:$('case-cohort').value,stage:$('case-stage').value,sla:$('case-sla').value};}
function renderReport(){
 if(!model){$('case-report-content').innerHTML='<p>No valid case analysis is available. Check the investigation settings.</p>';['case-print','case-report-download'].forEach(id=>$(id).disabled=true);return;}
 const settings=scope();if(CaseEngine.timestamp(settings.review)===null||settings.review<model.asOf){$('case-report-content').innerHTML='<p>Choose a valid proposed review date on or after '+esc(model.asOf)+' in Scope & handover.</p>';['case-print','case-report-download'].forEach(id=>$(id).disabled=true);return;}
 reportText=CaseEngine.report(model,settings);
 $('case-report-content').innerHTML=reportText.split('\n\n').map(part=>{const lines=part.split('\n'),first=lines.shift();if(first.startsWith('# ')||first.startsWith('## ')){const tag=first.startsWith('## ')?'h3':'h2';return '<'+tag+'>'+esc(first.replace(/^#+ /,''))+'</'+tag+'>'+(lines.length?'<p>'+esc(lines.join('\n')).replace(/\n/g,'<br>')+'</p>':'');}return '<p>'+esc(part).replace(/\n/g,'<br>')+'</p>';}).join('');
 ['case-print','case-report-download'].forEach(id=>$(id).disabled=false);
}
function render(){
 if(!data)return;
 try{model=CaseEngine.analyse(data,filters());$('case-status').textContent='Fictional history · '+data.asOf+' · '+(model.filters.team||'all teams')+' · '+(model.filters.cohort||'both entry cohorts');$('case-metrics').disabled=false;
 const bottleneck=model.bottleneck;
 const selected=model.rows.find(r=>r.stage===selectedStage)||bottleneck;
 const chartMax=Math.max(1,...model.rows.filter(r=>r.completed>=5).map(r=>r.median??0));
 const chart='<section class="case-chart" aria-label="Typical completed stage time"><div class="case-chart-head"><div><span class="case-label">STAGE TIME AT A GLANCE</span><h3>Where is the time going?</h3></div><p>Typical calendar days after leaving each stage. Choose a stage for the next question and owner.</p></div>'+model.rows.map(r=>'<button type="button" class="case-chart-row'+(selected?.stage===r.stage?' is-focus':'')+'" data-case-stage-action="'+esc(r.stage)+'" aria-pressed="'+(selected?.stage===r.stage)+'" aria-label="'+esc(r.stage)+': '+(r.completed<5?'too few completed records':format(r.median)+' typical days')+'. Show suggested action."><span class="case-chart-label">'+esc(r.stage)+'<small>'+r.completed+' completed records</small></span><span class="case-chart-track" aria-hidden="true"><i style="width:'+(r.completed<5?0:Math.max(0,Math.min(100,(r.median??0)/chartMax*100)))+'%"></i></span><b>'+(r.completed<5?'Too few records':format(r.median)+' days')+'</b></button>').join('')+'<p class="case-chart-note">The longest bar points to a question to investigate, not a proven cause. Stages with fewer than five completed records are not compared here.</p></section>';
 const nextCheck=selected&&selected.completed>=5?(stageChecks[selected.stage]||['Recruiting lead','Review the stage definition and the handoff with the team.']):['Recruiting lead','Check the date records and gather more completed examples before choosing a process change.'];
 $('case-analysis').innerHTML='<div class="case-stats"><article class="case-stat"><span>Applications in view</span><strong>'+model.applications+'</strong><small>Fictional applications in the selected group</small></article><article class="case-stat"><span>Stage dates we can use</span><strong>'+format(model.coverage)+'%</strong><small>'+model.excluded+' records need date checks</small></article><article class="case-stat"><span>Longest typical stage</span><strong>'+(bottleneck?format(bottleneck.median)+' days':'Unavailable')+'</strong><small>'+(bottleneck?esc(bottleneck.stage)+' · '+bottleneck.completed+' completed records':'Too few completed records to compare')+'</small></article></div>'+
 chart+
 '<div class="case-grid"><article class="case-card case-tint"><span class="case-label">ACTION TO VALIDATE · SELECTED STAGE</span><h3>'+(selected&&selected.completed>=5?'Check the '+esc(selected.stage.toLowerCase())+' handoff.':'Confirm the data first.')+'</h3><p>'+esc(nextCheck[1])+'</p><p><b>Suggested owner:</b> '+esc(nextCheck[0])+'. <b>Then:</b> agree one small pilot only after checking the underlying workflow.</p></article><article class="case-card"><span class="case-label">SECOND CHECK</span><h3>'+(model.excluded?'Reconcile '+model.excluded+' date gaps.':'Keep the stage definitions consistent.')+'</h3><p>'+(model.excluded?'The Recruiting Operations owner should sample the affected records against the source before setting a target.':'Check whether different teams use the same entry and exit definitions before comparing their figures.')+'</p></article></div>'+
 '<div class="case-card case-comparison"><span class="case-label">TEST THE PATTERN</span><h3>Does it hold across teams and cohorts?</h3><div class="case-compare"><button data-case-team="Engineering" aria-pressed="'+(model.filters.team==='Engineering')+'">Engineering</button><button data-case-team="Commercial" aria-pressed="'+(model.filters.team==='Commercial')+'">Commercial</button><button data-case-cohort="October" aria-pressed="'+(model.filters.cohort==='October')+'">October</button><button data-case-reset="true">Reset</button></div><p>Recent applications have had less time to reach an outcome, so compare similar groups before acting.</p></div>'+
 '<details class="case-question"><summary>See the detailed stage figures</summary><div class="case-table-wrap"><table class="case-table"><caption style="text-align:left;padding:18px;font-weight:600">Where candidates spend time · fictional evidence</caption><thead><tr><th>Stage</th><th>Moved forward</th><th>Typical time after leaving</th><th>Still waiting</th><th>Date gaps</th></tr></thead><tbody>'+model.rows.map(r=>'<tr><td><b>'+esc(r.stage)+'</b><small>'+r.entered+' applications entered</small></td><td>'+format(r.progression)+'%<small>Of '+r.resolved+' applications with a known outcome</small><div class="case-bar" aria-hidden="true"><i style="width:'+Math.max(0,Math.min(100,r.progression??0))+'%"></i></div></td><td>'+format(r.median)+' days<small>Based on '+r.completed+' completed records'+(r.completed<5?' · interpret cautiously':'')+'</small></td><td>'+r.active+' active<small>'+r.overdue+' past the '+model.filters.sla+'-day review point</small></td><td>'+r.excluded+'<small>Cannot be timed reliably</small></td></tr>').join('')+'</tbody></table></div></details>'+
 '<details class="case-question"><summary>How are these figures calculated?</summary><p>Typical time is the median number of calendar days between entering and leaving a stage. Applications still in a stage are shown separately. Missing or inconsistent dates are left out of time calculations. “Moved forward” counts progressed or hired applications among those with a known exit outcome. Small groups may be unstable. These records do not measure time to fill or quality of hire.</p></details>';
 $('case-analysis').querySelectorAll('[data-case-stage-action]').forEach(b=>b.onclick=()=>{selectedStage=b.dataset.caseStageAction;render();[...$('case-analysis').querySelectorAll('[data-case-stage-action]')].find(x=>x.dataset.caseStageAction===selectedStage)?.focus();});
 $('case-analysis').querySelectorAll('[data-case-team]').forEach(b=>b.onclick=()=>{selectedStage=null;$('case-team').value=b.dataset.caseTeam;$('case-role').value='';roles();render();});
 $('case-analysis').querySelectorAll('[data-case-cohort]').forEach(b=>b.onclick=()=>{selectedStage=null;$('case-cohort').value=b.dataset.caseCohort;render();});
 $('case-analysis').querySelectorAll('[data-case-reset]').forEach(b=>b.onclick=()=>{selectedStage=null;$('case-team').value='Engineering';$('case-role').value='';$('case-cohort').value='';$('case-stage').value='';$('case-sla').value='7';roles();render();});
 renderReport();
 }catch(e){model=null;reportText='';$('case-status').textContent=e.message;$('case-analysis').innerHTML='';$('case-metrics').disabled=true;renderReport();}
}
$('case-team').onchange=()=>{selectedStage=null;roles();render();};['case-role','case-cohort','case-stage','case-sla'].forEach(id=>$(id).onchange=()=>{selectedStage=null;render();});['case-objective','case-target','case-owner','case-review'].forEach(id=>$(id).oninput=renderReport);
$('case-metrics').onclick=()=>{if(model)download('fictional-case-filtered-metrics.csv',CaseEngine.metricsCSV(model),'text/csv;charset=utf-8');};
$('case-report-download').onclick=()=>{renderReport();if(!$('case-report-download').disabled)download('fictional-customer-engagement-report.md',reportText,'text/markdown;charset=utf-8');};
$('case-print').onclick=()=>{renderReport();if($('case-print').disabled)return;document.body.classList.add('case-print');try{window.print();}finally{document.body.classList.remove('case-print');}};
$('case-check-answer').onclick=()=>{const answer=document.querySelector('input[name="case-answer"]:checked'),output=$('case-quiz-feedback');output.hidden=false;output.textContent=!answer?'Choose a response first.':answer.value==='validate'?'That response tests the evidence before attributing a cause. Check completeness and role mix, inspect scheduling and feedback timestamps, then agree an action with the people who can change the process.':'This jumps from a descriptive metric to a cause or solution. Ask what is missing, compare like-for-like groups and inspect the underlying workflow before judging people or prescribing reminders.';};
$('case-guide').onclick=()=>download('customer-guide-interpreting-stage-delays.md',guide(),'text/markdown;charset=utf-8');
function guide(){return '# A customer guide to interpreting stage delays\n\nFictional educational example by John Hazelton.\n\n1. Agree what entering and leaving each stage means.\n2. Look at completed stages and people still waiting separately.\n3. Check missing dates; never turn missing dates into zero.\n4. Compare similar roles and time periods before assigning a cause.\n5. Check scheduling and feedback evidence; agree one owner and an escalation rule.\n6. Try one change and review a comparable group. A shorter typical time alone does not prove what caused it.\n\nThe CSM can reinforce routine definitions and agreed actions. Escalate complex analysis or recurring data conflicts to RecOps.\n\nThese records cannot establish candidate quality or hiring outcomes. No native Ashby configuration is claimed.\n';}
async function loadCase(){try{const response=await fetch('case-history.json');if(!response.ok)throw Error('History unavailable');data=await response.json();roles();$('case-stage').innerHTML='<option value="">All stages</option>'+data.stages.map(s=>'<option>'+esc(s)+'</option>').join('');render();}catch{$('case-status').textContent='The fictional history could not load. Reload to retry; the existing record health check is available below.';}}
loadCase();
})();
